import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/fyne.html","title":"fyne","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.39,"words":118},"filePathRelative":"fyne.md"}`),a={name:`fyne.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="fyne" tabindex="-1"><a class="header-anchor" href="#fyne"><span>fyne</span></a></h1><p><a href="./Go.html">Go</a>のGUIツールキット。</p><ul><li><a href="https://docs.fyne.io/" target="_blank" rel="noopener noreferrer">Fyne Documentation</a></li></ul><h2 id="デモを動かす" tabindex="-1"><a class="header-anchor" href="#デモを動かす"><span>デモを動かす</span></a></h2><p><a href="https://docs.fyne.io/started/quick/" target="_blank" rel="noopener noreferrer">Quick Start - Fyne Documentation</a></p><p>に従いデモを動かしてみる。 ボタンの効きとかが悪いのは気になるが、機能的にはちょっとしたの書くにはいいかもしれん。</p><p>DemoのEntryやFormが今やりたい事に似ているな。</p><h2 id="hello-world" tabindex="-1"><a class="header-anchor" href="#hello-world"><span>hello world</span></a></h2><p>hello worldをやっていく。</p><p><a href="https://docs.fyne.io/started/hello/" target="_blank" rel="noopener noreferrer">Creating your first Fyne app - Fyne Documentation</a></p><p>なんかhello worldをつくってgo buildを呼んだら<code>fyne.io/fyne/v2/app@v2.8.</code> とかが無いとか言われるが、適当にgo getしていったら３つ目くらいで一通り入った。</p><p>このページよりもそこに貼られている動画の方が良さそうだな。go getとかをやっている。</p><h2 id="テキストボックスのあるアプリ" tabindex="-1"><a class="header-anchor" href="#テキストボックスのあるアプリ"><span>テキストボックスのあるアプリ</span></a></h2><p>Finderから新しいブログのエントリを作るのに、いちいちファイル作ってVSCodeで開いてコピペするのがかったるい。 ファイルを作るのとテキストをコピペするのをまとめてやりたい。</p><p>という事でシェルスクリプトからテキストエリアとsubmit, cancelを持つだけのアプリを作って、それをコマンドラインから呼びたい。</p><p>UIとしては以下に似ているか。</p><ul><li><a href="https://apps.fyne.io/apps/com.github.able8.base64-encoder-decoder/" target="_blank" rel="noopener noreferrer">Base64 Encoder / Decoder · Fyne Apps</a><ul><li><a href="https://github.com/able8/base64-encoder-decoder" target="_blank" rel="noopener noreferrer">able8/base64-encoder-decoder: A simple cross-platform GUI app to convert text to Base64 or decode Base64 to text. Using Go &amp; Fyne.</a></li></ul></li></ul>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};